#!/usr/bin/env bash
#
# Weekly refresh of the Instagram access token.
# RUN ON THE SERVER AS ROOT (systemd unit elitepro-instagram-token.service invokes it).
#
#   sudo bash /var/www/eliteproinfra/shared/aws-instagram-token.sh
#
# INSTALLED BY HAND, root-owned (like aws-backup.sh) — never by the deploy,
# which runs as `elite`: a root-run script `elite` can rewrite is a privilege
# escalation. See deploy/AWS.md "Instagram token" for the install commands.
#
# WHY: Instagram-Login tokens live 60 days and can only be refreshed while still
# valid — once one lapses it must be regenerated by hand in the Meta App
# Dashboard, and the home-page reels go dark until someone notices. Refreshing
# weekly leaves ~8 retries before expiry.
#
# WHAT IT DOES
#   1. reads INSTAGRAM_ACCESS_TOKEN from Parameter Store (the source of truth)
#   2. exchanges it for a fresh 60-day token
#   3. proves the new token works, then writes it back to Parameter Store
#   4. re-renders shared/.env.local and reloads PM2 so the app uses it
#   5. publishes ElitePro/Website InstagramTokenRefreshOk (1/0) for the alarm
#
# The token never appears on a command line (and so never in `ps` or
# /proc/*/cmdline): curl reads it from a 600 temp file, and put-parameter takes
# it through --cli-input-json.
#
# Meta refuses to refresh a token younger than 24 hours; a run right after a
# manual regeneration fails harmlessly and the next week's run succeeds.

set -euo pipefail

APP_ROOT=/var/www/eliteproinfra
APP_NAME=eliteproinfra
REGION=ap-south-1
PARAM=/elitepro-website/prod/INSTAGRAM_ACCESS_TOKEN
API=https://graph.instagram.com

log()    { printf '[%s] %s\n' "$(date -u +%H:%M:%S)" "$1"; }
metric() {
  aws cloudwatch put-metric-data --region "$REGION" --namespace ElitePro/Website \
    --metric-name InstagramTokenRefreshOk --value "$1" >/dev/null 2>&1 || true
}
fail()   { printf '[%s] INSTAGRAM TOKEN REFRESH FAILED: %s\n' "$(date -u +%H:%M:%S)" "$1" >&2; metric 0; exit 1; }

[ "$(id -u)" = "0" ] || fail "must run as root (render-env.sh writes shared/.env.local)"

WORK="$(mktemp -d)"
chmod 700 "$WORK"
trap 'rm -rf "$WORK"' EXIT

# ------------------------------------------------------------ current token
aws ssm get-parameter --region "$REGION" --name "$PARAM" --with-decryption \
  --query Parameter.Value --output text > "$WORK/old" 2>/dev/null \
  || fail "could not read $PARAM from Parameter Store"
[ -s "$WORK/old" ] || fail "$PARAM is empty"
printf 'access_token=%s' "$(tr -d '\r\n' < "$WORK/old")" > "$WORK/old.q"

# ------------------------------------------------------------------ refresh
log "refreshing token"
curl -sS --max-time 30 -G "$API/refresh_access_token" \
  --data grant_type=ig_refresh_token --data-urlencode "@$WORK/old.q" \
  > "$WORK/refresh.json" || fail "refresh request did not complete"

if ! jq -e '.access_token | strings' "$WORK/refresh.json" >/dev/null; then
  # The error message carries no token, so it is safe to log.
  fail "$(jq -r '.error.message // "unexpected response"' "$WORK/refresh.json" 2>/dev/null || echo 'non-JSON response')"
fi
jq -r .access_token "$WORK/refresh.json" > "$WORK/new"
DAYS=$(jq -r '((.expires_in // 0) / 86400 | floor)' "$WORK/refresh.json")

# --------------------------------------------- prove it before storing it
printf 'access_token=%s' "$(cat "$WORK/new")" > "$WORK/new.q"
curl -sS --max-time 30 -G "$API/me" --data fields=id \
  --data-urlencode "@$WORK/new.q" > "$WORK/me.json" || fail "verification request did not complete"
jq -e '.id | strings' "$WORK/me.json" >/dev/null \
  || fail "new token did not validate: $(jq -r '.error.message // "unexpected response"' "$WORK/me.json" 2>/dev/null)"

# ------------------------------------------------------------------- store
jq -n --arg name "$PARAM" --rawfile value "$WORK/new" \
  '{Name: $name, Value: ($value | rtrimstr("\n")), Type: "SecureString", Overwrite: true}' \
  > "$WORK/put.json"
aws ssm put-parameter --region "$REGION" --cli-input-json "file://$WORK/put.json" >/dev/null \
  || fail "could not write $PARAM"
log "stored new token (valid ~${DAYS} days)"

# ------------------------------------------------------------------ apply
bash "$APP_ROOT/shared/render-env.sh"
sudo -u elite -H pm2 reload "$APP_NAME" --update-env >/dev/null \
  || fail "token stored, but PM2 reload failed — run: sudo -u elite -H pm2 reload $APP_NAME --update-env"

metric 1
log "done"
